Clase Libro
    Privado Definir disponible Como Entero;

    Metodo Constructor()
        Este.disponible <- 1;
    FinMetodo

    Publico Metodo Prestar()
        Este.disponible <- 0;
    FinMetodo

    Publico Metodo Disponible() Como Entero
        Retornar Este.disponible;
    FinMetodo
FinClase

Clase Biblioteca
    Privado Definir libro Como Libro;

    Metodo Constructor()
        Este.libro <- Nuevo Libro();
    FinMetodo

    Publico Metodo Prestar()
        Este.libro.Prestar();
    FinMetodo

    Publico Metodo Disponible() Como Entero
        Retornar Este.libro.Disponible();
    FinMetodo
FinClase

Proceso EjecutarBiblioteca
    Definir prestar Como Entero;
    Definir biblioteca Como Biblioteca;
    Leer prestar;
    biblioteca <- Nuevo Biblioteca();
    Si prestar = 1 Entonces
        biblioteca.Prestar();
    FinSi
    Escribir biblioteca.Disponible();
FinProceso
